[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Customers should not have a cart inside shelf aisles whose usable cross-width is single-file, defined by opposing shelves and narrow width rather than by fixed coordinates so the rule transfers across rotated or rearranged layouts.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    2
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file_shelf_aisle",
    "text": "Customers should not push a cart into a single-file shelf aisle, using the relational geometry of the destination aisle rather than the observed aisle coordinates.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    2
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "single_file_shelf_aisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_shelf_aisle_with_cart"
    }
  },
  {
    "id": "no_item_interaction_with_cart_in_single_file_aisle",
    "text": "Customers should not handle shelf items while holding a cart in a single-file shelf aisle, which captures the cart-free picking behavior without tying the rule to a particular product location.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
