                  "le": [
                    "freeWidthH",
                    2
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "A customer who parks or releases a cart must later retrieve a cart before finishing, making the cart separation a temporary accommodation rather than abandonment and therefore independent of where the parking spot is located.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cart_parked": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cart_retrieved": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_parked",
      "discharge": "cart_retrieved"
    }
  },
  {
    "id": "retrieve_cart_after_tight_aisle_excursion",
    "text": "After entering or moving through a single-file shelf aisle without the cart, the customer must later retrieve the cart, generalizing the observed out-and-back excursions by aisle geometry rather than by item coordinates.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    2
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "move_into_single_file_without_cart": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        },
        "cart_retrieved": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "move_into_single_file_without_cart",
      "discharge": "cart_retrieved"
    }
  },
  {
    "id": "park_cart_only_in_wide_unobstructed_area",
    "text": "When a cart is left behind, it should be parked only in a wide non-shelf-adjacent area so it does not block browsing or narrow passage, using clearance and shelf adjacency rather than a store-specific parking coordinate.",
    "abstraction": {
      "state_properties": {
        "wide_unobstructed_cart_parking_area": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "cart_parked": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_parked",
          {
            "not": "wide_unobstructed_cart_parking_area"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Customers should not leave the store without their cart, a behavior-level exit rule that remains meaningful if the exit moves or the route to it changes.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_before_shopping",
    "text": "Customers are obliged to obtain a cart before proceeding with the shopping trip, explaining the initial cart interaction without depending on the entrance, cart station, or exit coordinates.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  }
]

